import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); int t = Integer.parseInt(br.readLine()); while (t-- > 0) { String s = br.readLine(); int n = s.length(); int[] freq = new int[26]; for (int i = 0; i < n / 2; i++) { freq[s.charAt(i) - 'a']++; } int start = (n % 2 == 0) ? n / 2 : (n / 2) + 1; for (int i = start; i < n; i++) { freq[s.charAt(i) - 'a']--; } boolean isLap = true; for (int count : freq) { if (count != 0) { isLap = false; break; } } if (isLap) { System.out.println("YES"); } else { System.out.println("NO"); } } } }